// Editorial card layout; pagination preserves every recommendation.
export function renderMemoCards({title,sections},makeCanvas=()=>document.createElement('canvas')){
 const width=1080,left=96,bodyX=152,right=984,maxWidth=right-bodyX,maxHeight=1800,footerHeight=172,bottom=maxHeight-footerHeight-76;
 const measure=makeCanvas();measure.width=width;measure.height=maxHeight;const ctx=measure.getContext('2d');
 if(!ctx)throw new Error('Canvas unavailable');
 function wrap(text,font,limit=maxWidth){ctx.font=font;const lines=[];for(const paragraph of String(text).trim().replace(/\r\n?/g,'\n').replace(/\n{3,}/g,'\n\n').split('\n')){if(!paragraph.trim()){lines.push('');continue}let line='';for(const word of paragraph.trim().split(/\s+/)){const candidate=line?line+' '+word:word;if(ctx.measureText(candidate).width<=limit){line=candidate;continue}if(line){lines.push(line);line=''}for(const ch of word){if(ctx.measureText(line+ch).width>limit&&line){lines.push(line);line=''}line+=ch}}lines.push(line)}return lines}
 const titleLines=wrap(title,'40px Georgia',right-left),start=352+titleLines.length*50+66;
 const pages=[[]];let page=pages[0],y=start;
 function next(){page=[];pages.push(page);y=start}
 function heading(label,index,continued=false){const lines=wrap(label.toUpperCase()+(continued?' · ПРОДОЛЖЕНИЕ':''),'22px Arial');if(page.length)page.push({rule:true,y:y-25});page.push({number:String(index+1).padStart(2,'0'),y});for(const text of lines){page.push({text,y,font:'22px Arial',color:'#667464',height:29});y+=32}y+=19}
 for(const [index,{label,value}] of sections.entries()){const lines=wrap(value||'Уточнить у мастера','32px Georgia');const headingHeight=wrap(label.toUpperCase(),'22px Arial').length*32+19;const blockHeight=headingHeight+lines.length*48;
 if(page.length&&y+blockHeight>bottom&&blockHeight<=(bottom-start)*.45)next();
 if(y+headingHeight+Math.min(2,lines.length)*48>bottom)next();heading(label,index);
 for(let j=0;j<lines.length;j++){if(y+48>bottom){next();heading(label,index,true)}page.push({text:lines[j],y,font:'32px Georgia',color:'#273b31',height:40});y+=48}y+=57;
 }
 return pages.map((rows,i)=>{const last=rows.at(-1),contentEnd=last?last.y+last.height:start;const height=Math.min(maxHeight,Math.max(1160,Math.ceil(contentEnd+76+footerHeight)));const footerY=height-footerHeight;
 const canvas=makeCanvas();canvas.width=width;canvas.height=height;const c=canvas.getContext('2d');c.fillStyle='#f8f5ed';c.fillRect(0,0,width,height);c.fillStyle='#eae1d2';c.fillRect(0,0,width,262);c.textBaseline='top';
 // Restrained gold rules, generous masthead spacing and an inset border.
 c.strokeStyle='#a99265';c.lineWidth=1;c.strokeRect(28,28,width-56,206);c.textAlign='center';c.fillStyle='#3d4035';c.font='76px Georgia';c.fillText('V A L E R I',width/2,68);c.font='18px Arial';c.fillStyle='#796849';c.fillText('H A I R   S T U D I O',width/2,169);c.textAlign='left';
 c.fillStyle='#947c51';c.font='19px Arial';c.fillText('ПЕРСОНАЛЬНАЯ ПАМЯТКА ПО УХОДУ',left,305);c.fillStyle='#273b31';c.font='40px Georgia';titleLines.forEach((line,n)=>c.fillText(line,left,352+n*50));
 for(const row of rows){if(row.rule){c.strokeStyle='#dfd7c6';c.beginPath();c.moveTo(bodyX,row.y);c.lineTo(right,row.y);c.stroke();continue}if(row.number){c.font='italic 25px Georgia';c.fillStyle='#aa946d';c.fillText(row.number,left,row.y-1);continue}c.font=row.font;c.fillStyle=row.color;c.fillText(row.text,bodyX,row.y)}
 c.strokeStyle='#b39b70';c.beginPath();c.moveTo(left,footerY);c.lineTo(right,footerY);c.stroke();c.fillStyle='#273b31';c.font='italic 25px Georgia';c.fillText('С заботой о ваших волосах,',left,footerY+28);c.font='20px Arial';c.fillText('VALERI HAIR STUDIO',left,footerY+67);c.font='21px Arial';c.textAlign='right';c.fillText('+375 (33) 394-50-22',right,footerY+30);c.fillText('valerihairstudio.ru',right,footerY+65);c.font='17px Arial';c.fillStyle='#8a8c7c';c.fillText(`${i+1} / ${pages.length}`,right,footerY+121);c.textAlign='left';c.fillText('РЕКОМЕНДАЦИИ ВАШЕГО МАСТЕРА',left,footerY+121);return canvas});
}
export async function createMemoFiles(data){const cards=renderMemoCards(data);return Promise.all(cards.map((canvas,i)=>new Promise((resolve,reject)=>canvas.toBlob(blob=>blob?resolve(new File([blob],`VALERI-pamyatka-${i+1}.png`,{type:'image/png'})):reject(new Error('PNG encoding failed')),'image/png'))))}
export function canShareFiles(files){try{return !!navigator.share&&!!navigator.canShare?.({files})}catch{return false}}
export function initMemoImage({getData}){
 const $=s=>document.querySelector(s),dialog=$('#memo-image-dialog'),status=$('#memo-image-status');let files=[],urls=[],revision=0;
 function cleanup(){revision++;urls.forEach(url=>URL.revokeObjectURL(url));urls=[];files=[];$('#memo-image-pages').replaceChildren();$('#memo-image-send').disabled=true}
 async function prepare(){cleanup();const current=revision;status.textContent='Готовим изображение…';dialog.showModal();try{const result=await createMemoFiles(getData());if(current!==revision||!dialog.open)return;files=result;files.forEach((file,i)=>{const url=URL.createObjectURL(file);urls.push(url);const figure=document.createElement('figure'),img=document.createElement('img'),link=document.createElement('a'),actions=document.createElement('div'),copy=document.createElement('button'),send=document.createElement('button'),open=document.createElement('a');img.src=url;img.alt=`Памятка VALERI — страница ${i+1}`;img.width=1080;link.href=url;link.download=file.name;link.className='primary';link.textContent=files.length===1?'Скачать изображение PNG':`Скачать страницу ${i+1}`;actions.className='memo-file-actions';copy.type='button';copy.className='memo-copy-image';copy.textContent=files.length===1?'Скопировать изображение':`Скопировать страницу ${i+1}`;copy.disabled=!navigator.clipboard?.write||typeof ClipboardItem==='undefined';copy.title=copy.disabled?'Скопировать изображение нельзя в этом браузере. Используйте скачивание.':'';copy.onclick=async()=>{copy.disabled=true;try{await navigator.clipboard.write([new ClipboardItem({'image/png':file})]);status.textContent=`${files.length===1?'Изображение':`Страница ${i+1}`} скопировано. Откройте переписку в браузере и вставьте картинку: Ctrl+V или ⌘V. Если чат не принимает вставку, скачайте PNG и прикрепите его кнопкой фото.`}catch{status.textContent='Браузер не разрешил копирование изображения. Скачайте PNG и прикрепите его в переписке кнопкой фото.'}finally{copy.disabled=false}};send.type='button';send.className='primary';send.textContent=files.length===1?'Отправить с телефона':`Отправить страницу ${i+1}`;send.disabled=!canShareFiles([file]);send.onclick=()=>shareFiles([file],send);open.href=url;open.target='_blank';open.rel='noopener';open.className='memo-open-image';open.textContent='Открыть картинку';actions.append(copy,link,send,open);figure.append(img,actions);$('#memo-image-pages').append(figure)});const can=canShareFiles(files);$('#memo-image-send').disabled=!can;status.textContent=can?'Изображение готово. Отправьте файлом или скопируйте картинку для переписки в браузере.':'Используйте отправку отдельной страницы ниже. Если она недоступна, откройте сайт в Safari или Chrome, либо сохраните картинку и прикрепите её в чате.'}catch{if(current===revision)status.textContent='Не удалось создать изображение. Закройте окно и попробуйте ещё раз или используйте печать / PDF.'}}
 $('#memo-share').onclick=prepare;$('#memo-image-close').onclick=()=>dialog.close();dialog.addEventListener('close',cleanup);
 async function shareFiles(selected,button){if(!selected.length)return;const current=revision;button.disabled=true;try{await navigator.share({files:selected});if(current===revision)status.textContent='Изображение передано в меню отправки. Выберите приложение и завершите отправку.'}catch(e){if(current===revision)status.textContent=e.name==='AbortError'?'Отправка отменена. Можно повторить или скачать изображение.':'Не удалось передать файл. Попробуйте отправить одну страницу или откройте картинку, сохраните её и прикрепите в чате.'}finally{if(dialog.open&&current===revision)button.disabled=!canShareFiles(selected)}}
 $('#memo-image-send').onclick=()=>shareFiles(files,$('#memo-image-send'));
}
